package local.shiguang.album;
import android.app.*;import android.os.*;import android.graphics.ImageDecoder;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class OriginalActivity extends Activity {
 Drawable drawable;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setColorMode(android.content.pm.ActivityInfo.COLOR_MODE_HDR);getWindow().setStatusBarColor(0xff101b16);getWindow().setNavigationBarColor(0xff101b16);android.widget.LinearLayout layout=new android.widget.LinearLayout(this);layout.setOrientation(1);layout.setBackgroundColor(0xff101b16);Button back=new Button(this);back.setText("返回整理 · 系统解码原画 / HDR");back.setOnClickListener(v->finish());layout.addView(back);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);layout.addView(image,new LinearLayout.LayoutParams(-1,0,1));getWindow().setDecorFitsSystemWindows(false);layout.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});setContentView(layout);layout.requestApplyInsets();new Thread(()->{try{drawable=ImageDecoder.decodeDrawable(ImageDecoder.createSource(getContentResolver(),getIntent().getData()));runOnUiThread(()->{image.setImageDrawable(drawable);if(drawable instanceof AnimatedImageDrawable)((AnimatedImageDrawable)drawable).start();});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->{Toast.makeText(this,"当前系统无法解码或内存不足，请使用系统相册查看",Toast.LENGTH_LONG).show();finish();});}}).start();}
 @Override protected void onDestroy(){if(drawable instanceof AnimatedImageDrawable)((AnimatedImageDrawable)drawable).stop();super.onDestroy();}
}
